 768	static int nvmet_pci_epf_get_prp_list(struct nvmet_pci_epf_ctrl *ctrl, u64 prp,
 769					      size_t xfer_len, __le64 *prps)
 770	{
 771		size_t nr_prps = (xfer_len + ctrl->mps_mask) >> ctrl->mps_shift;
 772		u32 length;
 773		int ret;
